n24863.content:
\begin{definition}[Simple Ring] A ring $R$ is simple if the only
  two-sided-ideals of $R$ are ${0}$ and $R$. An algebra is simple if it is
  simple as a ring.
  \leanok
  \lean{IsSimpleRing}
\end{definition}

n24865.content:
\begin{lemma}
  \label{lem:center-simple-ring}
  Let $A$ be a simple ring, then centre of $A$ is a field. \leanok
  \lean{IsSimpleRing.isField_center}
\end{lemma}

n24866.content:
\begin{proof}
  Let $0\ne x$ be an element of centre of $A$. Then $I := \{xy | y\in A\}$ is a
  two-sided-ideal of $A$. Since $0\ne x\in I$, we have that $I = A$. Therefore
  $1 \in I$, hence $x$ is invertible.
\end{proof}

n24867.content:
\begin{definition}[Central Algebras]
  Let $R$ be a ring and $A$ an $R$-algebra, we say $A$ is central if and only if
  the centre of $A$ is $R$
  \leanok
  \lean{Algebra.IsCentral}
\end{definition}

n24868.content:
\begin{remark}
  Every commutative ring is a central algebra over itself.
\end{remark}

n24869.content:
\begin{remark}
  Simpleness is invariant under ring isomorphism and centrality is invariant
  under algebra isomorphism.
\end{remark}

n24870.content:
\begin{lemma}
  \label{lem:opp-central}
  If $A$ is a central $R$-algerba, $A^{\opp}$ is also central.
  \leanok
  \lean{CSA_op_is_CSA}.
\end{lemma}

n24871.content:
\begin{lemma}\label{lem:simple-ring-iff}
  $R$ is a simple ring if and only if any ring homomorphism $f : R \to S$ either
  injective or $S$ is the trivial ring. \leanok
  \lean{IsSimpleRing.iff_injective_ringHom_or_subsingleton_codomain}
\end{lemma}

n24873.content:
\begin{remark}
  If $A$ is a simple $R$-algebra, ``ring homomorphism'' in \cref{lem:simple-ring-iff} can be replaced with $R$-algebra homomorphism.
\end{remark}

n24874.content:
\begin{corollary}\label{cor:alghom-bijective-of-dim-eq}
  Assume $R$ is a field. Let $A, B$ be finite dimensional $R$-algebras where $A$
  is simple as well. Then any $R$-algebra homomorphism $f:A\to B$ is bijective
  if $\dim_{R}A=\dim_{R}B$. 
  \leanok
  \lean{bijective_of_dim_eq_of_isCentralSimple}
  % \uses{lem:simple-ring-iff}
\end{corollary}

n24875.content:
\begin{proof}
  By~\cref{lem:simple-ring-iff}, $f$is injective. Then
  $\dim_{K}\im f = \dim_{K} B - \dim_{K}\ker f = \dim_{K}B$ meaning that $f$ is
  surjective.
\end{proof}

n24876.content:
\begin{lemma}
  \label{lem:tensor-central}
  If $A$ and $B$ are central $K$-algebras, $A\otimes_{K}B$ is a central
  $K$-algebra as well.
  \leanok
  \lean{IsCentralSimple.TensorProduct.isCentral}
  % \uses{cor:center-tensor-center}
\end{lemma}

n24877.content:
\begin{proof}
  Assume $A$ and $B$ are central algebras, then
  by~\cref{cor:center-tensor-center}
  $Z\left(A\otimes_{R}B\right)=Z\left(A\right)\otimes_{R}Z\left(B\right)=R\otimes_{R}R=R$.
\end{proof}

n24878.content:
\begin{theorem}
  \label{thm:tensor-csa}
  If $A$ is a simple $K$-algebra and $B$ is a central simple $K$-algebra,
  $A\otimes_{K}B$ is a central simple $K$-algebra as well. 
  \leanok
  \lean{IsCentralSimple.TensorProduct.simple}
  % \uses{lem:tensor-central, lem:expand-tensor-in-basis}
\end{theorem}

n24880.content:
\begin{corollary}\label{cor:csa-basechange}
  Central simple algebras are stable under base change. That is, if $L/K$ is a
  field extension and $D$ is a central simple algebra over $K$, then
  $L\otimes_{K} D$ is central simple over $L$. \leanok
  \lean{IsCentralSimple.baseChange}
  % \uses{thm:tensor-csa, cor:center-tensor-center}
\end{corollary}

n24882.content:
\begin{theorem}\label{thm:tensor-simple-implies-simple}
  If $A\otimes_{K} B$ is a simple ring, then $A$ and $B$ are both simple.
  \leanok
  \lean{IsCentralSimple.TensorProduct.simple}
  % \uses{lem:simple-ring-iff}
\end{theorem}

n24883.content:
\begin{proof}
  By symmetry, we only prove that $A$ is simple.
  If $A$ or $B$ is the trivial ring then $A\otimes_{K} B$ is the trivial ring, a contradiction. Thus we assume both $A$ and $B$ are non-trivial. Suppose $A$ is not simple, by~\cref{lem:simple-ring-iff}, there exists a non-trivial $K$-algebra $A'$ and a $K$-algebra homomorphism $f : A \to A'$ such that $\ker f \not= \{0\}$. Let $F : A \otimes_{K} B\to A'\otimes_{K} B$ be the base change of $f$, then since $A\otimes_{K} B$ is simple and $A'\otimes B$ is non-trivial ($A'$ is non-trivial and $B$ is faithfully flat because $B$ is free), we conclude that $F$ is injective. Then we have that
  \begin{center}
    \begin{tikzcd}
      0 \arrow{r}{0} & A \otimes_{K} B \arrow{r}{F} & A'\otimes_K B
    \end{tikzcd}
  \end{center}
  is exact. Since $B$ is faithfully flat as a $K$-module, tensorig with $B$ reflects exact sequences, therefore
  \begin{center}
    \begin{tikzcd}
      0 \arrow{r}{0} & A \arrow{r}{f} & A'
    \end{tikzcd}
  \end{center}
  is exact as well. This is contradiction since $f$ is not injective.
\end{proof}

n24884.content:
\begin{definition}[Subfield]
  For any field $K$ and $K$-algebra $A$, a subfield $B \subseteq A$ is a commutative $K$-subalgebra of $A$ that is closed under inverse for any non-zero member.
  \leanok
  \lean{SubField}
\end{definition}

n24885.content:
\begin{remark}
  Subfields inherit a natural ordering from subalgebras.
\end{remark}

n24886.content:
\begin{lemma}\label{lem:dim-maximal-subfield}
  Let $k$ be a maximal subfield of $D$,
  \[
    \dim_{K}D = {\left(\dim_{K}k\right)}^{2}.
  \]
  \leanok
  \lean{dim_max_subfield}
  % \uses{lem:dim-centralizer}
\end{lemma}

n24888.content:
\begin{lemma}\label{lem:tfae-subfield}
  Suppose $L$ is a subfield of $A$, the following are equivalent:
  \begin{enumerate}
    \item $L$ = $C_{A}(L)$
    \item $\dim_{K}A = {\left(\dim_{K}L\right)}^{2}$
    \item for any commutative $K$-subalgebra $L' \subseteq A$, $L \subseteq L'$ implies $L = L'$
  \end{enumerate}
  \leanok
  \lean{cor_two_1to2, cor_two_2to3, cor_two_3to1}
  % \uses{lem:dim-centralizer}
\end{lemma}

n24889.content:
\begin{proof}
  We prove the following:
  \begin{itemize}
    \item ``1. implies 2.'': this is~\cref{lem:dim-centralizer}.
    \item ``2. implies 1.'': Since $L$ is commutative, we always have $L \subseteq C_{A}(L)$. Hence we only need to show $\dim_{K}L = \dim_{K}C_{A}(L)$. This is because by~\cref{lem:dim-centralizer}, we have that $\dim_{K}A = \dim_{K}L\cdot \dim_{K}C_{A}(L)$ and by 2. we have $\dim_{K}L\cdot \dim_{K}C_{A}(L)= \dim_{K}L\cdot \dim_{K}L$.
    \item ``2. implies 3.'': Since 2. implies 1., we assume $L = C_{A}(L)$, therefore all we need is to prove $L' \subseteq C_{A}(L)$. Let $x \in L'$ and $y \in L \subseteq L'$, we need to show $xy = yx$ which is commutativity of $L'$.
    \item ``3. implies 1.'': By commutativity of $L$, we always have $L \subseteq C_{A}(L)$. For the other direction, suppose $C_{A}(L)\not\subseteq L$, then there exists some $a \in C_{A}(L)$ but not in $L$. Consider $L' = L(a)$, by 3., we have $L' = L$ which is a contradiction.
  \end{itemize}
\end{proof}

n24890.content:
\begin{construction}\label{con:morita-eqv-functor0}
  \leanok
  \lean{matrix_smul_vec_def}
  If $M$ is an $R$-module, we have a natural
  $\Mat_{n}(R)$-module structure on $\widehat{M}:=M^{n}$ given by
  $(m_{ij})\cdot (v_{k})=\sum_{j}m_{ij}\cdot v_{j}$. If $f : M \to N$ is an
  $R$-linear map, then $\widehat{f} : M^{n}\to N^{n}$ given by
  $(v_{i}) \mapsto (f(v_{i}))$ is a $\Mat_{n}(R)$-linear map. Thus we have a
  well-defined functor $\MOD_{R} \Longrightarrow \MOD_{\Mat_{n}(R)}$.
\end{construction}

n24891.content:
\begin{remark}
  Note that all modules are assumed to be left modules; when we need to consider
  right $R$-modules, we will consider left $R^{\opp}$-modules instead. We use
  $\delta_{ij}$ to denote the matrix whose $(i,j)$-th entry is $1$ and $0$
  elsewhere. $\delta_{ij}$ forms a basis for matrices.
\end{remark}

n24893.content:
\begin{theorem}[Morita Equivalence]\label{thm:morita}
  The functors constructed in \cref{con:morita-eqv-functor0} and
  \cref{con:morita-eqv-functor1} form an equivalence of category.
  \leanok
  \lean{moritaEquivalentToMatrix}
  % \uses{con:morita-eqv-functor0, con:morita-eqv-functor1}
\end{theorem}

n24894.content:
\begin{proof}
  Let $M$ be an $R$-module, then the unit $\widetilde{\widehat{M}} \cong M$ is
  given by
  \[
    \begin{aligned}
      x \mapsto \sum_{j} x_{j} \\
      (x,0,\dots,0) \mapsfrom x
    \end{aligned}
  \]

  Let $M$ be an $\Mat_{n}(R)$-module, then the counit
  $\widehat{\widetilde{M}}\cong M$ is given by $m \mapsto (\delta_{i0}\cdot m)$.
  This map is both injective and surjective.
\end{proof}

n24895.content:
\begin{lemma}\label{lem:isomorphic-simple-mod}
  Let $M$ and $N$ be simple $A$-modules, then $M$ and $N$ are isomorphic as
  $A$-modules.
  \leanok
  \lean{linearEquiv_of_isSimpleModule_over_simple_ring}
  % \uses{thm:wed-artin-algebra, thm:morita}
\end{lemma}

n24897.content:
\begin{lemma}\label{lem:direct-sum-simple-mod}
  Let $M$ be an $A$-module, there exists a simple $A$-module $S$ such that $M$
  is a direct sum of copies of $S$, i.e. $M \cong \bigoplus_{i \in \iota} S$ for
  some indexing set $\iota$. \leanok
  \lean{directSum_simple_module_over_simple_ring}
  % \uses{thm:wed-artin-algebra, thm:morita, lem:direct-sum-simple-mod2}
\end{lemma}

n24899.content:
\begin{remark}
  Note that by~\cref{lem:isomorphic-simple-mod}, any two simple $A$-module are
  isomorphic, hence for any $A$-module $M$ and {\em any} simple $A$-module $S$,
  we can write $M$ as a direct sum of copies of $S$.
\end{remark}

n24900.content:
\begin{lemma}\label{lem:iso-of-dim-eq}
  Let $M$ and $N$ be two finite $A$-module with compatible $k$-action. Then $M$
  and $N$ are isomorphic as $A$-module if and only if $\dim_{k} M$ and
  $\dim_{k} N$ are equal. \leanok
  \lean{linearEquiv_iff_finrank_eq_over_simple_ring}
  % \uses{lem:direct-sum-simple-mod}
\end{lemma}

n24902.content:
\begin{lemma}\label{lem:exists-simple-mod}
  $D^{n}$ is a simple $A$-module where the module structure is given by pulling
  back the $\Mat_{n}(D)$-module structure of $D^{n}$.
  \leanok
  \lean{simple_mod_of_wedderburn}
  % \uses{thm:morita}
\end{lemma}

n24903.content:
\begin{proof}
  By~\cref{thm:morita}, we have $\MOD_{A}\cong\MOD_{D}\cong\MOD_{\Mat_{n}(D)}$.
  Since $D$ is a simple $D$-module, $D^{n}$ is a simple $\Mat_{n}(D)$ module and
  consequently, a simple $A$-module.
\end{proof}

n24904.content:
\begin{remark}
  Note that any $A$-linear endomorphism of $D^{n}$ is $\Mat_{n}(D)$-linear, and
  vice versa. Thus we have
  $\End_{A}\left(D^{n}\right)\cong \End_{\Mat_{n}(D)}\left(D^{n}\right)$ as
  $k$-algebras.
\end{remark}

n24907.content:
\begin{lemma}\label{lem:end-simple-iso}
  Let $M$ be a simple $A$-module, then $\End_{A} M\cong D^{\opp}$ as
  $k$-algebras.
  \leanok
  \lean{end_simple_mod_of_wedderburn'}
  % \uses{thm:morita, lem:isomorphic-simple-mod, lem:end-vec-iso}
\end{lemma}

n24908.content:
\begin{proof}
  By~\cref{thm:morita}, $D^{n}$ is simple as $A$-module; hence
  by~\cref{lem:isomorphic-simple-mod}, $D^{n}$ and $M$ are isomorphic as
  $A$-module. \Cref{lem:end-vec-iso} gives the desired result.
\end{proof}

n24909.content:
\begin{remark}
  In particular, if $M$ is a simple $A$-module, then $\End_{A}M$ is a simple
  $k$-algbera.
\end{remark}

n24910.content:
\begin{lemma}
  Let $M$ be a simple $A$-module, then $\End_{A}M$ has finite $k$-dimension.
  \leanok
  \lean{end_simple_mod_finite}
  % \uses{thm:wed}
\end{lemma}

n24911.content:
\begin{proof}
  By~\cref{thm:wed}, such $D$ and $n$ always exists. Hence we only need to show
  $D^{\opp}$ has finite $k$-dimension. Since $\dim_{k}A=\dim_{k}\Mat_{n}(D)$ are
  both finite, we conclude $D^{\opp}$ is finite as a $k$-vector space by pulling
  back the finiteness along $D \hookrightarrow \Mat_{n}(D)$.
\end{proof}

n24913.content:
\begin{definition}[Balanced Module]\label{def:balanced-mod}
  \leanok
  \lean{IsBalanced}
  For any ring $A$ and $A$-module $M$, we say $M$ is a
  balanced $A$-module, if the $A$-linear map $A \to \End_{\End_{A}M}M$ is
  surjective.
\end{definition}

n24914.content:
\begin{remark}
  Balancedness is invariant under linear isomorphism.
\end{remark}

n24915.content:
\begin{lemma}\label{lem:balanced-self}
  For any ring $A$, $A$ is balanced as $A$-module. \leanok
\end{lemma}

n24916.content:
\begin{proof}
  If $f \in \End_{\End_{A}M}A$, then the image of $f(1)$ under
  $A \to\End_{\End_{A}}A$ is $f$ again.
\end{proof}

n24919.content:
\begin{lemma}\label{lem:iso-end-end}
  For any simple $A$-module $M$, we have $A \cong \End_{\End_{A}M}M$ as
  $k$-algebras.
\end{lemma}

n24920.content:
\begin{proof}
  The canonical map $A \to \End_{\End_{A}M}M$ is both injective and surjective,
  as $M$ is a balanced $A$-module and $A$ is a simple ring.
\end{proof}

n24921.content:
\begin{lemma}\label{lem:expand-tensor-in-basis}
  Let $M$ and $N$ be $R$-modules such that $\mathcal{C}_{i\in\iota}$ is a basis
  for $N$, then every elements of $x \in M \otimes_{R} N$ can be uniquely
  written as $\sum_{i\in\iota}m_{i}\otimes \mathcal{C}_{i}$ where only finitely
  many $m_{i}$'s are non-zero
\end{lemma}

n24922.content:
\begin{proof}
  Given the basis $\mathcal{C}$, we have $R$-linear isomorphism
  $N \cong\bigoplus_{i\in\iota}R$, hence
  $M\otimes_{R}N \cong \bigoplus_{i\in\iota}(M\otimes_{R}R)\cong\bigoplus_{i\in\iota}M$
  as $R$-modules.
\end{proof}

n24923.content:
\begin{lemma}
  \label{lem:submodule-tensor-submodule}
  Let $K$ be a field, $M$ and $N$ be flat $K$-modules. Suppose $p \subseteq M$
  and $q \subseteq N$ are $K$-submodules, then
  $(p \otimes_{K} N) \sqcap (M \otimes_{K} q) = p \otimes_{K} q$ as
  $K$-submodules.
\end{lemma}

n24924.content:
\begin{proof}
  The hard direction is to show
  $(p \otimes_{R} N) \sqcap (M \otimes_{R} q) \le p \otimes_{R} q$. Consider the
  following diagram:
  \begin{center}
    \begin{tikzcd}
      p \otimes_{K} q \ar[r, "u"] \ar[d, "\alpha"] & M \otimes_{K} q \ar[r, "v"] \ar[d, "\beta"] & {}^{M}/_{p} \otimes_{K} q \ar[d, "\gamma"] \\
      p \otimes_{K} N \ar[r, "u'"] & M \otimes_{K} N \ar[r, "v'"] & ^{M}/_{p}
      \otimes_{K} N
    \end{tikzcd}
  \end{center}
  Since $^{M}/_{p}$ is flat, $\gamma$ is injective. Let
  $z \in (p \otimes_{R} N) \sqcap (M \otimes_{R} q) = \im \beta \sqcap \im u'$.
  By abusing notation, replace $z$ with some elements of $M \otimes_{K} q$ and
  continue with $\beta(z)\in\im \beta \sqcap \im u'$. Since
  $v'(\beta(z))=\gamma(v(z))$ and that $\beta(z)\in \im u'$, we conclude that
  $\gamma(v(z))=0$, that is $z\in\ker v=\im u$. We abuse notation again, let
  $z \in p \otimes_{K} q$, we need to show
  $\beta(u(z))\in\im \beta \sqcap \im u'$, but $\beta\circ u=u'\circ\alpha$, we
  finish the proof.
\end{proof}

n24925.content:
\begin{lemma}\label{lem:sup-centralizer}
  Let $S, T$ be two subalgebras of $A$, then
  $C_{A}(S\sqcup T)=C_{A}(S)\sqcap C_{A}(T)$. \leanok
  \lean{Subalgebra.centralizer_sup}
\end{lemma}

n24926.content:
\begin{lemma}\label{lem:centralizer-inclusion-tensor}
  If we assume $B$ is free as $R$-module, then for any $R$-subalgebra $S$, we
  have that $C_{A\otimes_{R}B}\left(\im\left(S\to A\otimes_{R}B\right)\right)$
  is $C_{A}(S) \otimes_{R} B$
  \leanok
  \lean{centralizer_inclusionRight}
  % \uses{lem:expand-tensor-in-basis}
\end{lemma}

n24929.content:
\begin{corollary}\label{cor:centralizer-tensor-centralizer}
  Assume $R$ is a field. Let $S$ and $T$ be $R$-subalgebras of $A$ and $B$
  respectively. Then $C_{A\otimes_{R}B}\left(S\otimes_{R}T\right)$ is equal to
  $C_{A}(S)\otimes_{R}C_{B}(T)$
  \leanok
  \lean{centralizer_tensor_centralizer}
  % \uses{lem:submodule-tensor-submodule}
\end{corollary}

n24931.content:
\begin{corollary}
  \label{cor:center-tensor-center}
  Assume $R$ is a field. The centre of $A\otimes_{R} B$ is
  $Z\left(A\right)\otimes_{R}Z\left(B\right)$. 
  \leanok
  \lean{IsCentralSimple.center_tensorProduct}
  % \uses{cor:centralizer-tensor-centralizer}
\end{corollary}

n24933.content:
\begin{construction}
  \label{con:self-tensor-opp-iso-end}
  Let $R$ be a commutative ring and $A$ an $R$-algebra. Then we
  have an $R$-algebra homomorphism $A\otimes_{R}A^{\opp} \cong \End_{R}A$ given
  by $a\otimes 1 \mapsto (a\cdot\bullet)$ and
  $1\otimes a \mapsto (\bullet\cdot a)$. When $R$ is a field and $A$ is a finite dimensional central simple algebra, this morphism is an isomorphism by~\cref{cor:alghom-bijective-of-dim-eq}.
\end{construction}

n24935.content:
\begin{construction}
  \label{con:matrix-matrix}
  Let $A$ be an $R$-algebra. Then $\Mat_{m}\left(\Mat_{n}(A)\right) \cong \Mat_{mn}(A)$.
  The trick is to think $\Mat_{m}A$ as $\{0,\dots,m-1\} \times \{0,\dots,m-1\} \to A$. Since the indexing set $\{0,\dots,mn-1\}$ bijects with $\left(\{0,\dots,m-1\}\times\{0,\dots,n-1\}\right)$, the isomorphism is just function currying, function uncurrying, precomposing and postcomposing bijections.
  \leanok
  \lean{Matrix.comp}
\end{construction}

n24936.content:
\begin{construction}
  \label{con:matrix-tensor-matrix}
  Let $A, B$ be $R$-algebras. Then $\Mat_{mn}\left(A\otimes_{R}B\right)\cong\Mat_{m}(A)\otimes_{R}\Mat_{n}B$ as $K$-algebras. We first construct $R$-algebra isomorphism $A \otimes_{R}\Mat_{n}(R) \cong \Mat_{n}(A)$:
  \[
    \begin{aligned}
      & a \otimes 1 \mapsto \diag{a}~\text{and}~ 1\otimes (m_{ij}) \mapsto (m_{ij})\\
      & \sum_{i,j} m_{ij}\otimes \delta_{ij}\mapsfrom (m_{ij}),
    \end{aligned}
  \]
  where $\diag$ is the diagonal matrix and $\delta_{ij}$ the matrix whose only non-zero entry is at $(i,j)$-th and is equal to $1$.
  Thus $\Mat_{m}(A)\otimes_{R}\Mat_{n}(B)\cong \left(A\otimes_{R}B\right)\otimes_{R} \left(\Mat_{m}(R)\otimes_{R} \Mat_{n}(R)\right)$ as $R$-algebra.
  The Kronecker product gives us an $R$-algebra map $\Mat_{m}(R)\otimes_{R}\Mat_{n}(R) \to \Mat_{mn}(R)$. We want this map to be an isomorphism. By~\cref{lem:simple-ring-iff}, we only need to prove it to be surjective: for all $\delta_{ij} \in \Mat_{mn}(R)$, we interpret $\Mat_{mn}(R)$ as a function $\{0,\dots,m-1\}\times\{0,\dots,n-1\}\to R$, then $\delta_{ij}$ is the image of $\delta_{ab}\otimes \delta_{cd} \in \Mat_{m}(R)\otimes_{R}\Mat_{n}(R)$ where $i = (a, c)$ and $j = (b,d)$. Combine everything together, we see $\Mat_{mn}\left(A\otimes_{R}B\right)$ is isomorphic to $\Mat_{mn}\left(A\otimes_{R} B\right)$ as $R$-algebras.
  \leanok
  \lean{BrauerGroup.matrix_eqv, BrauerGroup.kroneckerMatrixTensor'}
  % \uses{lem:simple-ring-iff}
\end{construction}

n24937.content:
\begin{lemma}[minimal ideal of simple rings]\label{lemma:min-ideal-simple-ring}
  Let $A$ be a ring and $I$ a non-trivial minimal left ideal of $A$, then $I$ is
  a simple $A$-module.
  \leanok
  \lean{minimal_ideal_isSimpleModule}
\end{lemma}

n24938.content:
\begin{proof}
  Let $J\le I$ be an $A$-submodule of $I$, suppose $J$ is non-trivial, we prove
  that $J=I$. Then the image $J'$ of $J$ under $I \hookrightarrow A$ is a
  non-trivial left ideal of $A$. Since $I \hookrightarrow A$ is injective, it is
  sufficient to prove that $J' = I$. This is because $J'\le I$ and $J' \not< J$.
\end{proof}

n24939.content:
\begin{lemma}
  Let $A$ be a simple ring and $I$ a non-trivial left ideal. One can write
  $1 \in A$ as $\sum_{i=0}^{n}x_{i}y_{i}$ for some $x_{i}\in I$ and
  $y_{i} \in A$.
\end{lemma}

n24940.content:
\begin{proof}
  Let $I'$ be the two-sided ideal spanned by $I$. Then since $A$ is a simple
  ring, $I' = A$. Thus $1 \in I'$. One can write $1 \in A$ as
  $\sum_{i}a_{i}x_{i}b_{i}$ for some $x_{i}\in I$ and $a_{i},b_{i}\in A$, since
  $I$ is a left ideal $a_{i}x_{i}\in I$ as well.
\end{proof}

n24943.content:
\begin{theorem}[Wedderburn]\label{thm:wed}
  Let $A$ be a simple ring and $I$ a non-trivial minimal left ideal. Then there
  exists a non-zero $n \in \mathbb{N}$ such that $A \cong I^{n}$ as $A$-modules.
  \leanok
  \lean{Wedderburn_Artin.aux.equivIdeal}
  \uses{lemma:min-ideal-simple-ring}
  \uses{lemma:min-ideal-simple-ring}
\end{theorem}

n24945.content:
\begin{theorem}[Wedderburn-Artin (Ideal)]
  Let $A$ be an Artinian simple ring. There exists a non-zero $n$ and an ideal
  $I \subseteq A$ such that $I$ is simple as an $A$-module and $A \cong I^{n}$
  as $A$-module.
  \label{thm:wed-artin-ideal}
  \leanok
  \lean{Wedderburn_Artin_ideal_version}
  \uses{thm:wed}
\end{theorem}

n24946.content:
\begin{proof}
  By~\cref{thm:wed}, we only need a minimal left ideal. Since $A$ is Artinian,
  such ideal exists.
\end{proof}

n24947.content:
\begin{theorem}[Wedderburn-Artin (Algebra)] \label{thm:wed-artin-algebra}
 Let $K$ be a field and $B$ an finite dimensional simple algebra over $K$.
  There exists a non-zero $n\in\mathbb{N}$ and a division $K$-algebra $S$ such
  that $B \cong \Mat_{n}(S)$.
  \leanok
  \lean{Wedderburn_Artin_algebra_version}
  \uses{thm:wed-artin-ideal, con:end-vec-iso-matrix}
\end{theorem}

n24949.content:
\begin{theorem}[Uniqueness of Wedderburn-Artin theorem]\label{thm:wed-artin-uniq}
  Let $B$ be a
  finite-dimensional simple $K$-algebra. Suppose $B$ is isomorphic as
  $k$-algebras to both $\Mat_{n}(D)$ and $\Mat_{n'}(D')$ where $n, n'$ are
  non-zero natural numbers and $D, D'$ are $k$-division algebra, then $n = n'$
  and $D \cong D'$ as $k$-algebras.\label{thm:wed-artin-unique} \leanok
  \lean{Wedderburn_Artin_uniqueness₀}
  \uses{lem:end-simple-iso}
\end{theorem}

n24951.content:
\begin{construction}
  For any $K$-algebra homomorphism $f : B \to A$, we give $M$ a
  $B \otimes_{K}\End_{A}M$-module structure by defining $(b\otimes l)\cdot m$ to
  be $f(b)\cdot l(m)$. To emphasis $f$, we denote $M$ with the
  $B\otimes_{K}\End_{A}M$-module structure by $M^{f}$.
  \leanok
  \lean{IsMod}
\end{construction}

n24952.content:
\begin{lemma}
  Let $f : B \to A$ be a $K$-algebra homomorphism, $M^{f}$ is finitely generated
  as a $B\otimes_{K}\End_{A}M$-module.
  \leanok
  \lean{module_inst_findim}
\end{lemma}

n24954.content:
\begin{remark}
  Given that $B$ is simple, any $k$-algebra homomorphism $f : B\to A$ injective;
  therefore by finite $K$-dimensionality of $A$, $B$ is finite $K$-dimensional
  as well.
\end{remark}

n24955.content:
\begin{lemma}
  \label{lem:iso-fg}
  Let $f,g : B \to A$ be two $K$-algebra homomorphisms. Then $M^{f}$ and $M^{g}$
  are isomorphic as $B\otimes_{K}\End_{A}M$-module.
  \leanok
  \lean{iso_fg}
  % \uses{lem:iso-of-dim-eq}
\end{lemma}

n24956.content:
\begin{proof}
  By~\cref{lem:iso-of-dim-eq}, it is sufficient to prove
  $\dim_{K}M^{f}=\dim_{K}M^{g}$. But as $K$-vector space, $M^{f}$ and $M^{g}$
  are {\em literally\/} $M$.
\end{proof}

n24957.content:
\begin{theorem}[Skolem-Noether]\label{thm:skolem-noether}
  Let $f, g : B \to A$ be two $K$-algebra homomorphism. Then $f$ and $g$ differ
  only by a conjugation. That is there exists a unit $x \in A^{\times}$ such
  that $g = x f x^{-1}$.
  \leanok
  \lean{SkolemNoether'}
  % \uses{lem:exists-simple-mod, lem:iso-fg, lem:iso-end-end}
\end{theorem}

n24959.content:
\begin{lemma}
  \label{lem:centralizer-mul-left-le}
  The centralizer of $\McL_{A}$ in $\End_{F}A$ is smaller than or equal to
  $\McR_{A}$:
  \[
    C_{\End_{F}A}\left(\McL_{A}\right) \le \McR_{A}.
  \]
  \leanok
  \lean{centralizer_mulLeft_le_of_isCentralSimple}
  % \uses{con:self-tensor-opp-iso-end}
\end{lemma}

n24961.content:
\begin{remark}\label{rem:mul-left-center-linear}
  For any $F$-algebra $B$, every element in $C_{\End_{F}B}\left(\McL_{B}\right)$
  is in fact $Z(B)$-linear. Let $x\in C_{\End_{F}B}\left(\McL_{B}\right)$,
  $z\in Z(B)$ and $b \in B$, we have $x(z\cdot b) = z\cdot x(b)$ because $x$
  commutes with the linear map $\left(z\cdot\bullet\right)$.
\end{remark}

n24962.content:
\begin{remark}
  $A$ is a $Z(A)$-algebra whose algebra structure is given by
  $Z(A)\hookrightarrow A$. By~\cref{lem:center-simple-ring}, $Z(A)$ is a field.
  $A$ is finite dimensional as a $Z(A)$-module because of the tower $A/Z(A)/F$.
\end{remark}

n24964.content:
\begin{proof}
   We prove the map $A^{\opp} \to \McR_{A}$ is bijective. It is injective
   because if $\left(\bullet \cdot a\right) = \left(\bullet\cdot b\right)$, then
   $a = 1 \cdot a = 1 \cdot b = b$. The map is surjective by the definition of
   $\McR_{A}$.
 \end{proof}

n24965.content:
\begin{lemma}\label{lem:centralizer-mul-left-eq-mul-right}
   Let $B$ be any simple $F$-algebra ({\em not\/} necessarily central). The
   centralizer of $\McL_{B}$ in $\End_{F}B$ is equal to $\McR_{B}$.
   \leanok
   \lean{centralizer_mulLeft}
   % \uses{lem:centralizer-mul-left-le, rem:mul-left-center-linear}
 \end{lemma}

n24967.content:
\begin{construction}
   Let $B$ be any $F$-algebra and $S\subseteq B$ an $F$-subalgebra. For any
   $x\in B^{\times}$, we have that $x S x^{-1}:=\{xsx^{-1}|s\in S\}$ is an
   $F$-subalgebra of $B$ as well. We have the obvious $F$-algebra isomorphism
   $S \cong xSx^{-1}$ given by $s\mapsto xsx^{-1}$ and $x^{-1}tx\mapsfrom t$.
   Therefore $\dim_{F}S=\dim_{F}xSx^{-1}$ and $S$ is a simple ring if and only
   if $xSx^{-1}$ is a simple ring.
   \leanok
   \lean{Subalgebra.conj}
 \end{construction}

n24968.content:
\begin{lemma}
   \label{lem:centralizer-conj}
   Let $B$ be any $F$-algebra, $x \in B^{\times}$ and $S\subseteq B$ be an
   $F$-subalgebra of $B$, then $C_{B}(xSx^{-1})=x\left(C_{B}(S)\right)x^{-1}$.
   \leanok
   \lean{Subalgebra.conj_centralizer}
 \end{lemma}

n24969.content:
\begin{proof}
   If $a \in C_{B}\left(xSx^{-1}\right)$, then $x^{-1}ax$ is in $C_{B}(S)$.
   Conversely if $a$ is equal to $xbx^{-1}$ with $b\in C_{B}(S)$, then it is in
   $C_{B}\left(xSx^{-1}\right)$ as well.
 \end{proof}

n24970.content:
\begin{remark}
   For any finite dimensional $F$-module $B$, we have isomorphism
   $\End_{F}B \cong \Mat_{\dim_{F}B}F$ as $F$-algebras. Hence $\End_{F} B$ is a
   finite-dimensional central simple algebra over $F$.
 \end{remark}

n24971.content:
\begin{lemma}\label{lem:tensor-mul-right-simple}
   Let $S\subseteq A$ be a simple $F$-subalgebra, then
   $A \otimes_{F} \McR_{S}$ is a simple ring.
   \leanok
   % \uses{thm:tensor-csa, lem:mul-right-iso-opp}
 \end{lemma}

n24972.content:
\begin{proof}
   By~\cref{lem:mul-right-iso-opp}, we have
   $A\otimes \McR_{S}\cong A\otimes S^{\opp}$ as $F$-algebras. The claim follows
   from~\cref{thm:tensor-csa}.
 \end{proof}

n24973.content:
\begin{lemma}\label{lem:centralizer-tensor-end-eq-conj-tensor-mul-right}
   Let $S\subseteq A$ be a simple $F$-subalgebra, then there
   exists an $x\in \left(A\otimes_{F}\End_{F}S\right)^{\times}$ such that
   $C_{A}(S)\otimes_{F}\End_{F}S$ is isomorphic to
   $x\left(A\otimes_{F}\McR_{S}\right)x^{-1}$ as $F$-algebras.
   \leanok
   \lean{centralizer_isSimple.aux.step1}
   % \uses{lem:tensor-central,thm:tensor-csa, thm:skolem-noether, lem:centralizer-conj, lem:centralizer-inclusion-tensor,lem:centralizer-mul-left-eq-mul-right}
 \end{lemma}

n24975.content:
\begin{lemma}\label{lem:simple-centralizer}
   Let $S\subseteq A$ be a simple $F$-subalgebra, then
   $C_{A}(S)$ is simple as well.
   \leanok
   \lean{centralizer_isSimple}
   % \uses{lem:centralizer-tensor-end-eq-conj-tensor-mul-right, lem:tensor-mul-right-simple, thm:tensor-simple-implies-simple}
 \end{lemma}

n24977.content:
\begin{lemma}
   \label{lem:dim-centralizer}
   Let $S\subseteq A$ be a simple $F$-subalgebra. Then
   \[
     \dim_{F}C_{A}(S)\cdot\dim_{F}S=\dim_{F}A.
   \]
   \leanok
   \lean{dim_centralizer}
   % \uses{lem:centralizer-tensor-end-eq-conj-tensor-mul-right, lem:mul-right-iso-opp}
 \end{lemma}

n24979.content:
\begin{corollary}
  \label{cor:self-tensor-centralizer}
  Let $S \subseteq A$ be a central simple $F$-subalgebra,
  \[
    A \cong B \ox_{F} C_{A}(B).
  \]
  \leanok
  \lean{writeAsTensorProduct}
  % \uses{lem:simple-centralizer, thm:tensor-csa, cor:alghom-bijective-of-dim-eq, lem:dim-centralizer}
\end{corollary}

n24980.content:
\begin{proof}
  By~\cref{lem:simple-centralizer}, $C_{A}(B)$ is simple and by~\cref{thm:tensor-csa}, $B \ox_{F} C_{A}(B)$ is simple. Hence the map $B \ox_{F} C_{A}(B) \to A$ induced by $B \hookrightarrow A$ and $C_{A}(B) \hookrightarrow A$ is injective. By~\cref{cor:alghom-bijective-of-dim-eq}, we only need to show $\dim_{F}B\ox_{F}C_{A}(B) =\dim_{F}A$ which is precisely~\cref{lem:dim-centralizer}.
\end{proof}

n24981.content:
\begin{theorem}[Double Centralizer]\label{thm:double-centralizer}
   Let $S\subseteq A$ be a simple $F$-subalgebra, we have
   \[
     C_{A}\left(C_{A}(S)\right) = S.
   \]
   \leanok
   \lean{double_centralizer}
   % \uses{lem:simple-centralizer, lem:dim-centralizer}
 \end{theorem}

n24982.content:
\begin{proof}
  It is straightforward that $S \le C_{A}\left(C_{A}(S)\right)$. By~\cref{lem:simple-centralizer}, $C_{A}(S)$ is simple, hence $\dim_{F}C_{A}\left(C_{A}(S)\right)\cdot \dim_{F}C_{A}(S)=\dim_{F}A=\dim_{F}C_{A}(S)\cdot \dim_{F}S$ (by applying~\cref{lem:dim-centralizer} twice), i.e. $\dim_{F}C_{A}\left(C_{A}(S)\right) = \dim_{F}S$. This equality of dimension gives us the desired result.
\end{proof}

n24983.content:
\begin{remark}
  By~\cref{lem:tensor-central} and~\cref{thm:tensor-csa}, $\CSA$ is closed under tensor product, that is if $A, B\in\CSA$, we have $A\otimes_{K} B\in\CSA$ as well.
\end{remark}

n24984.content:
\begin{definition}[Brauer Equivalence]\label{def:br-eqv}
  For any two $A, B\in\CSA$, we say $A$ and $B$ are Brauer equivalent, when there exists $m, n \in \mathbb{N}_{\ge0}$ such that $\Mat_{m}(A)\cong \Mat_{n}B$ as $K$-algebras. We denote this relation as $A\sim_{\Br_{K}} B$, when $K$ is clear, we drop the subscript.
\end{definition}

n24991.content:
\begin{proof}
  Let $A\sim_{\Br}B$ and $B\sim_{\Br}C$; that is for some $m,n,p, q\in\mathbb{N}_{\ge0}$ we have $\Mat_{n}(A)\cong\Mat_{m}(B)$ and $\Mat_{p}(B)\cong \Mat_{q}(C)$ as $K$-algebras. Hence, from~\cref{con:matrix-matrix}, we have the following:
  \[
    \begin{aligned}
      \Mat_{np}(A)&\cong \Mat_{p}\left(\Mat_{n}(A)\right)\cong\Mat_{p}\left(\Mat_{m}(B)\right)\\
                  &\cong\Mat_{mp}(B)\cong\Mat_{m}\left(\Mat_{p}(B)\right)\\
      &\cong\Mat_{m}\left(\Mat_{q}(C)\right)\cong\Mat_{mq}(C).
    \end{aligned}
  \]
  In another word, $A\sim_{\Br}C$.
\end{proof}

n24993.content:
\begin{proof}
  We need to prove that for all $A, B, C, D \in \CSA$ such that $A\sim_{\Br} B$ and $C\sim_{\Br}D$, $A\otimes_{R}C \sim_{\Br} B\otimes_{R}D$ as well.
  Suppose $\Mat_{m}(A)\cong \Mat_{n}(B)$ as $K$-algebras and $\Mat_{p}(C)\cong\Mat_{q}(D)$, by~\cref{con:matrix-tensor-matrix}, we have
  \[
    \begin{aligned}
      \Mat_{mp}\left(A\otimes_{R} C\right)&\cong \Mat_{m}(A)\otimes_{R}\Mat_{p}(C) \\
                                          &\cong \Mat_{n}(B)\otimes_{R}\Mat_{q}(D)\\
      &\cong \Mat_{nq}\left(B\otimes_{R}D\right).
    \end{aligned}
  \]

\end{proof}

n24994.content:
\begin{construction}[Brauer Group]\label{con:br}
  $\Br(K)$ forms a group under $[A]_{\sim_{\Br}}\cdot[B]_{\sim_{\Br}}=[A\otimes_{K}B]_{\sim_{\Br}}$ with neutral element $[K]_{\sim_{\Br}}$ where $A, B\in\CSA$ and $[A]_{\sim_{Br}}^{-1}=[A^{\opp}]_{\sim_{\Br}}$. We need to prove the following properties:
  \begin{enumerate}
    \item associativity: for all $A, B, C\in\CSA$, $[A]_{\sim_{\Br}}\cdot\left([B]_{\sim_{\Br}}\cdot[C]_{\sim_{\Br}}\right)=\left([A]_{\sim_{\Br}}\cdot[B]_{\sim_{\Br}}\right)\cdot [C]_{\sim_{\Br}}$ because $A\ox_{R}\left(B\ox_{R}C\right)\cong \left(A\ox_{R}B\right)\ox_{R}C$ as $K$-algebras.
    \item neutral element: for all $A\in \CSA$, $[K]_{\sim_{\Br}}\cdot[A]_{\sim_{\Br}}=[A]_{\sim_{\Br}}=[A]_{\sim_{\Br}}\cdot [K]_{\sim_{\Br}}$. Since $[K]_{\sim_{\Br}}\cdot[A]_{\sim_{\Br}}=[K\ox_{K} A]_{\sim_{\Br}}$, in~\cref{con:matrix-tensor-matrix}, we see that $\Mat_{n}(A)\cong A\ox_{K}\Mat_{n}(K)$, by~\cref{lem:br-mul-wd}, $A\ox_{K}\Mat_{n}(K)$ is Brauer equivalent to $A\ox_{K} K$ since $K\sim_{\Br}\Mat_{n}(K)$.
    \item cancellation: for all $A \in \CSA$, we need $[A]_{\sim_{\Br}}\cdot[A^{\opp}]_{\sim_{\Br}}$, that is we want $A\ox_{K}A^{\opp}\sim_{\Br} K$. By~\cref{con:self-tensor-opp-iso-end}, we have $A\ox_{K}A^{\opp}\cong \End_{K}A$ which is isomorphic to $\Mat_{\dim_{K}A}(K)$ as $K$-algebras.
  \end{enumerate}
  \leanok
  \lean{BrauerGroup.Bruaer_Group}
  \uses{con:matrix-tensor-matrix,lem:br-mul-wd,con:self-tensor-opp-iso-end}
\end{construction}

n24995.content:
\begin{theorem}
  \label{thm:br-triv-alg-closed}
  If $K$ is algebraically closed, $\Br(K)$ is trivial; in particular $\br_{n}(\mathbb{C})$ is trivial.
  \leanok
  \lean{BrauerGroup.Alg_closed_eq_one}
  \uses{thm:wed-artin-algebra}
\end{theorem}

n24996.content:
\begin{proof}
  We need to show that every $A\in\CSA$ is isomorphic to $\Mat_{n}(K)$ for some $K$ when $K$ is algebraically closed. Indeed, by~\cref{thm:wed-artin-algebra}, $A \cong \Mat_{n}(D)$ for some division algebra $D$ and $n\in\nat_{\ge0}$. Since $K$ is algebraically closed and $D$ is an integral domain and finite dimensional, the structure morphism $\rho: K\to D$ is a isomorphism; therefore $A\cong \Mat_{n}(K)$.
\end{proof}

n24997.content:
\begin{lemma}
  \label{lem:common-div-alg}
Let $A, B \in \csa_{K}$. There exists a division $K$-algebra $D$ and non-zero $m,n\in\mathbb{N}$ such that $A\cong\mat_{m}(D)$ and $B\cong\mat_{n}(D)$ as $K$-algebras.
  \leanok
  \lean{IsBrauerEquivalent.exists_common_division_algebra}
  \uses{thm:wed-artin-algebra,thm:wed-artin-uniq}
\end{lemma}

n25002.content:
\begin{lemma}\label{lem:br-base-change-tower}
   Consider the tower of field extension $E/F/K$,
   \[
     \Br_{K}^{E} = \Br_{E}^{F}\circ\Br_{K}^{E}.
   \]
 \end{lemma}

n25003.content:
\begin{proof}
   If $A\in\CSA_{K}$, then $E\ox_{F}\left(F\ox_{K}A\right)$ is isomorphic to $E \ox_{F} A$ as $E$-algebras.
   \leanok
   \lean{BrauerGroupHom.baseChange_idem}
 \end{proof}

n25004.content:
\begin{corollary}
   $\Br$ forms a functor from category of field to category of abelian groups.
   \leanok
   \lean{BrauerGroupHom.Br}
   \uses{lem:br-base-change-self, lem:br-base-change-tower}
 \end{corollary}

n25005.content:
\begin{proof}
   This is the categorical version of~\cref{lem:br-base-change-self} and~\cref{lem:br-base-change-tower}.
 \end{proof}

n25006.content:
\begin{definition}[Relative Brauer Group]
   Let $E/K$ be a field extension, we define the relative Brauer group $\Br(E/K)$ to be the kernel of the base change morphism $\Br_{K}^{E}$.
   \leanok
   \lean{RelativeBrGroup}
   \uses{con:br-base-change}
 \end{definition}

n25007.content:
\begin{remark}
   Unpacking the definition of the relative Brauer group, we see that for any $A \in \CSA_{K}$, if $E\ox_{K}A\cong\mat_{n}(E)$ as $E$-algebras, then $\br^{E}_{K}\left([A]_{\sim_{\br}}\right)=1$.
 \end{remark}

n25008.content:
\begin{definition}[Splitting Field]
   For any field extension $E/K$ and any $K$-algebra $A$, we say $E$ is a splitting field of $A$ if and only if $E\ox_{K}A \cong \mat_{n}(E)$ as $E$-algebras for some non-zero $n$. We also say $E$ splits $A$ or $A$ is splited by $E$
   \leanok
   \lean{isSplit}
 \end{definition}

n25009.content:
\begin{theorem}
   \label{thm:split-iff-mem-relative}
   Let $E/K$ be a field extension and $A\in\csa_{K}$, $E$ splits $A$ if and only if $[A]_{\sim_{\br}}\in\br(E/K)$.
   \leanok
   \lean{BrauerGroup.split_iff}
   \uses{thm:wed-artin-algebra,thm:wed-artin-uniq}
 \end{theorem}

n25011.content:
\begin{remark}
   In light of~\cref{lem:br-base-change-tower}, if $K$ is algebraic closed then $K$ splits any $K$-algebra $A$. Indeed, $K$ splits $A$ if and only if $[A]_{\sim\br}$ but $[A]_{\sim\br}$ is equal to $1$.
 \end{remark}

n25012.content:
\begin{remark}
   If two $\csa_{K}$ are Brauer equivalent, in another word, $A \sim_{\br_{K}} B$, then $E$ splits $A$ if and only if $E$ splits $B$. Indeed, if $A$ and $B$ are equivalent, then $[A]_{\sim\br} \in \br(E/K)$ if and only if $[B]_{\sim\br}\in\br(E/K)$.
 \end{remark}

n25013.content:
\begin{lemma}
   \label{lem:good-rep-inv}
   Let $A\in\csa_{F}$ splitted by $K$. There exists a $B\in\csa_{F}$ such that
   \begin{itemize}
     \item $[A]_{\sim_{\br}}[B]_{\sim_{\br}}=1$
     \item there exists $F$-algebra map $K\hookrightarrow B$
     \item ${\left(\dim_{F}K\right)}^{2}=\dim_{F}B$.
   \end{itemize}
   \leanok
   \lean{exists_embedding_of_isSplit}
   % \uses{thm:double-centralizer, lem:simple-centralizer, cor:self-tensor-centralizer, lem:dim-centralizer}
 \end{lemma}

n25014.content:
\begin{proof}
   Since $K$ splits $A$, we find a non-zero natural number $n$ such that $K\ox_{F}A\cong\mat_{n}K\cong\End_{K}\left(K^{n}\right)$ as $K$-algebras.
   We define an $F$-algebra map $\iota: A\to\End_{F}\left(K^{n}\right)$ by
   \begin{center}
     \begin{tikzcd}
       A \arrow{r} & K \ox_{F} A \arrow{r}{\cong} & \End_K\left(K^n\right) \arrow{r}{|_{F}} & \End_F\left(K^n\right)
     \end{tikzcd},
   \end{center}
   where $|_{F}$ is restriction of scalars. Since $A$ is simple, $\iota$ is injective, therefore $A \cong \iota(A)$ as $F$-algebras. Define $B$ as $C_{\End_{F}\left(K^{n}\right)}(\iota(A))$, the centralizer of the range of $\iota$ in $\End_{F}\left(K^{n}\right)$.
   We construct an embedding $K \hookrightarrow B$ by $r \mapsto (r \cdot \bullet)$

   $B$ is a central $F$-algebra: if $x \in Z(B)$, then $x \in \iota(A)$ because by~\cref{thm:double-centralizer}, it is sufficient to prove that $x$ is in $C_{\End_{F}\left(K^{n}\right)}\left(B\right)$ which follows from the fact that $x \in Z(B)$. In fact, $x \in Z(\iota(A))$: suppose $a \in A$, we need to check $x \cdot \iota(a) = \iota(a)\cdot x$, this is the case because $B$ is defined as the centralizer of $\iota(A)$. Since $\iota(A) \cong A$ as $F$-algebras, $\iota(A)$ is $F$-central, hence $x \in F$.

   $B$ is a simple ring: by~\cref{lem:simple-centralizer}, it is sufficient to prove that $\iota(A)$ is a simple ring which comes from $A \cong \iota(A)$ as $F$-algebras.

   By~\cref{cor:self-tensor-centralizer}, we have $F$-algebra isomorphism $\End_{F}\left(K^{n}\right)\cong \iota(A)\ox_{F}B \cong A \ox_{F}B$. Since $\End_{F}\left(K^{n}\right)\cong\mat_{\dim_{F}\left(K^{n}\right)}\left(F\right)$ as $F$-algebras, we see that $[A]_{\sim_{\br}}$ and $[B]_{\sim_{\br}}$ are inverses.

   By~\cref{lem:dim-centralizer}, $\dim_{F}B\cdot \dim_{F}\iota(A) = \dim_{F}B\cdot\dim_{F}A = \dim_{F}\End_{F}\left(K^{n}\right) = {\left(\dim_{F}\left(K^{n}\right)\right)}^{2}={\left(\dim_{F}K\cdot \dim_{K}\left(K^{n}\right)\right)}^{2}=n^{2}\cdot{\left(\dim_{F}K\right)}^{2}$. On the other hand, since $K\ox_{F}A\cong\mat_{n}K$, we have $\dim_{F}K\ox_{F}A=\dim_{F}K\cdot\dim_{F}A=\dim_{F}\mat_{n}K=\dim_{F}K\dim_{K}\mat_{n}K=n^{2}\dim_{F}K$. Since $\dim_{F}K\ne 0$ , we conclude $\dim_{F}A=n^{2}$. Since $n\ne 0$ and $\dim_{F}(B)\cdot \dim_{F}(A)=n^{2}\dim_{F}(B)=n^{2}{\left(\dim_{F}K\right)}^{2}$, we get the desired result.

 \end{proof}

n25015.content:
\begin{corollary}\label{cor:good-rep}
   Let $A\in\csa_{F}$ splitted by $K$. There exists a $B \in \csa_{F}$ such that
   \begin{itemize}
     \item $[B]_{\sim_{\br}}=[A]_{\sim_{\br}}$
     \item there exists an $F$-algebra map $K\hookrightarrow B$
     \item  ${\left(\dim_{F}K\right)}^{2}=\dim_{F}B$.
   \end{itemize}
   % \uses{lem:good-rep-inv}
 \end{corollary}

n25016.content:
\begin{proof}
   Let $B$ and $\iota : K \hookrightarrow B$ be as in~\cref{lem:good-rep-inv}. Consider $B^{\opp}$ and $K \hookrightarrow B \to B^{\opp}$. This works.
 \end{proof}

n25017.content:
\begin{theorem}\label{thm:good-rep-iff-split}
   Let $A\in\csa_{F}$. $K$ splits $A$ if and only if there exists a $B\in\csa_{F}$ such that
   \begin{itemize}
     \item $[B]_{\sim_{\br}}=[A]_{\sim_{\br}}$
     \item there exists an $F$-algebra map $K \hookrightarrow B$
     \item ${\left(\dim_{F}K\right)}^{2}=\dim_{F}B$.
   \end{itemize}
   \leanok
   \lean{isSplit_iff_dimension}
   % \uses{cor:good-rep, cor:alghom-bijective-of-dim-eq}
 \end{theorem}

n25019.content:
\begin{definition}[Good Representation]\label{def:good-rep}
   For any $X \in \br(F)$, a $K$-good representation of $X$ is an $A \in \csa_{F}$ and an $F$-algebra map $K \hookrightarrow A$ such that $[A]_{\sim_{\br}} = X$ and $\dim_{F}A={\left(\dim_{F}K\right)}^{2}$. We often denote the $F$-algebra map $K \hookrightarrow A$ as $\iota$ or $\iota_{A}$.

   \leanok
   \lean{GoodRep}
 \end{definition}

n25020.content:
\begin{corollary}
   \label{cor:mem-relative-br-iff-good-rep}
   For any $X\in\br(F)$, $X\in\br(K/F)$ if and only if $X$ admits a good representation.
   \leanok
   \lean{mem_relativeBrGroup_iff_exists_goodRep}
   % \uses{thm:good-rep-iff-split, thm:split-iff-mem-relative}
 \end{corollary}

n25022.content:
\begin{lemma}
  The range $\iota_{A}(A)$ is a simple ring.
  \leanok
  \lean{GoodRep.ιRange}
\end{lemma}

n25023.content:
\begin{proof}
  Because $K$ is a simple ring, $\iota_{A}$ is injective therefore $\iota_{A}(A)\cong K$.
\end{proof}

n25025.content:
\begin{proof}
  In the language of~\cref{sec:subfield}, $\iota_{A}(A)$ is a subfield of $A$, hence by~\cref{lem:tfae-subfield}, we only need to show $\dim_{F}A = {\left(\dim_{F}\iota_{A}(A)\right)}^{2}$. But $\dim_{F}A={\left(\dim_{F}K\right)}^{2}$ and $\iota(A)\cong K$.
\end{proof}

n25026.content:
\begin{construction}\label{con:good-rep-mod}
  We give $A$ a $K$-module structure by {\em left\/} multiplication, that is for any $c \in K$ and $a \in A$, we define $c\cdot a$ to be $\iota_{A}(c)a$. Note that if $c \in F$ then $\iota_{A}(c)a = c \cdot a$, in another word, the $K$-action and the $F$-action on $A$ are compatible. Then $A$ is a finite dimensional $K$-vector space and $\dim_{K}A=\dim_{F}K$: indeed $\dim_{F}K\cdot\dim_{K}A = \dim_{F}K\cdot \dim_{F}K = \dim_{F}A$.
  \leanok
  \lean{GoodRep.dim_eq'}
\end{construction}

n25027.content:
\begin{lemma}\label{lem:good-rep-iso}
  If $A$ and $B$ are two good representations of $X$, then $A \cong B$ as $F$-algebras.
  \leanok
  \lean{GoodRep.exists_iso}
  % \uses{lem:common-div-alg}
\end{lemma}

n25028.content:
\begin{proof}
  By~\cref{lem:common-div-alg}, we find a division $F$-algebra $D$ and non-zero natural numbers $m, n$ such that $A \cong \mat_{m}(D)$ and $B \cong \mat_{n}(D)$ as $F$-algebras. Therefore
  \[
    \begin{aligned}
      {\left(\dim_{F}K\right)}^{2} &= \dim_{F}A &= m^{2}\dim_{F}D \\
      &= \dim_{F}B &= n^{2}\dim_{F}D.
    \end{aligned}
  \]
  Therefore $m = n$ and $A \cong \mat_{m}D =\mat_{n}D\cong B$.
\end{proof}

n25029.content:
\begin{remark}
  Since $\gal(K/F)$ acts on $K^{\star}$, for $x\in K^{\star}$,we feel free to write $\sigma\cdot x$ when it feels more readable than $\sigma(x)$, for example when there are nested brackets.
\end{remark}

n25030.content:
\begin{definition}[Conjugation Factor]
  \label{def:conj-factor}
  With respect to $A$, a conjugation factor of $\sigma$ is a unit $x_{\sigma} \in A^{\star}$ such that for all $c \in K$,
  \[
    x_{\sigma} \iota_{A}(c)x_{\sigma}^{-1} = \iota_{A}(\sigma \cdot c).
  \]

  A conjugation sequence is a sequence $x:\gal(K/F) \to A^{\star}$ such that for all $\sigma\in\gal(K/F)$, $x_{\sigma}$ is a conjugation factor of $\sigma$. When we want to stress $A$, we say $A$-conjugation factor and $A$-conjugation sequence.
  \leanok
  \lean{GoodRep.conjFactor}
\end{definition}

n25031.content:
\begin{remark}\label{rem:conj-factor-alternative-eq}
  When $x_{\sigma}$ is a conjugation factor of $\sigma$, the equalities $x_{\sigma}\iota_{A}(c) = x_{\sigma}\iota_{A}(\sigma(c))$ and $\iota_{A}(c)x_{\sigma}^{-1}=x_{\sigma}^{-1}\iota_{A}(\sigma(c))$ are also useful.
\end{remark}

n25032.content:
\begin{construction}\label{con:exists-conj-seq}
  $A$ has a conjugation sequence:
  let $\sigma \in \gal(K/F)$, we have two $F$-algebra homomorphisms $K \to A$ given by $\iota_{A}$ and $\iota_{A}\circ \sigma$. Applying~\cref{thm:skolem-noether} to $\iota_{A}$ and $\iota_{A}\circ \sigma$ gives us the desired conjugation factor.
  \leanok
  \lean{GoodRep.arbitraryConjFactor}
  % \uses{thm:skolem-noether}
\end{construction}

n25033.content:
\begin{construction}
  If $x$ is a conjugation factor of $\sigma$ and $y$ of $\tau$, then $xy$ is a conjugation factor of $\sigma\tau$. For any $c \in K$
  \[
    \iota_{A}(\sigma \cdot\tau(c)) = x\iota_{A}(\tau\cdot c)x^{-1} = xy\iota_{A}(c)y^{-1}x^{-1}=\left(xy\right)\iota_{A}{\left(xy\right)}^{-1}.
  \]
  \leanok
  \lean{GoodRep.mul'}
\end{construction}

n25034.content:
\begin{theorem}\label{thm:conj-seq-basis}
  If $x$ is an $A$-conjugation sequence, then $\{x_{\sigma}|\sigma\in \gal(K/F)\}$ is an $K$-linearly independent set. When $K/F$ is finite dimensional and Galois, $\{x_{\sigma}|\sigma\in \gal(K/F)\}$ is a $K$-basis for $A$.
  \leanok
  \lean{GoodRep.conjFactor_linearIndependent, GoodRep.conjFactorBasis}
  % \uses{con:good-rep-mod, def:conj-factor}
\end{theorem}

n25037.content:
\begin{lemma}\label{lem:2-cocycle-one-one}
  If $f \in \mathcal{B}^{2}(G, M)$ is a 2-cocycle and $x\in G$, we have
  \[
    \begin{aligned}
    f(1, x) &= f(1, 1) \\
    f(x, 1) &= x\cdot f(1, 1).
    \end{aligned}
  \]
\end{lemma}

n25038.content:
\begin{proof}
  Indeed:
  \[
    \begin{aligned}
      f(1\cdot 1, x)f(1, 1) &= (1\cdot f(1,x))f(1, 1\cdot x)  \\
      f(1, x)f(1, 1) &= f(1, x) f(1,x) \\
      f(1, x) &= f(1,1)
    \end{aligned}
  \] and
  \[
    \begin{aligned}
      f(x\cdot 1, 1)f(x, 1) &= (x\cdot f(1, 1))f(x, 1\cdot 1)\\
      f(x, 1)f(x, 1) &= (x\cdot f(1, 1))f(x, 1)\\
      f(x, 1) &= x \cdot f(1, 1).
    \end{aligned}
  \]
  \leanok
  \lean{CrossProductAlgebra.a_one_left, CrossProductAlgebra.a_one_right}
\end{proof}

n25039.content:
\begin{lemma}[Twisting Conjugation Factors]\label{lem:twist-spec1}
  If $x$ and $y$ are two conjugation factors of $\sigma$, then there exists a unique $c \in K$ such that $x = y\iota_{A}(c)$.
  \leanok
  \lean{GoodRep.conjFactor_rel, GoodRep.conjFactorTwistCoeff}
  % \uses{rem:conj-factor-alternative-eq, lem:centralizer-range-good-rep}
\end{lemma}

n25041.content:
\begin{remark}
  $\twist(x, x)$ is equal to $1$ by uniqueness.
\end{remark}

n25042.content:
\begin{remark}
  In fact, $\twist(x, y)$ is in $K^{\star}$ and $\twist(x, y)^{-1}=\twist(y, x)$.
\end{remark}

n25043.content:
\begin{lemma}\label{lem:twist-spec2}
  If $x$ and $y$ are conjugation factors for $\sigma$, $x=\iota_{A}(\sigma(\twist_{x, y}))y$.
  \leanok
  \lean{GoodRep.conjFactorTwistCoeff_spec'}
\end{lemma}

n25045.content:
\begin{construction}[Comparing Conjugation Factors]\label{con:compare-conj-factors}
  Let $x$ be a conjugation factor for $\sigma$, $y$ for $\tau$ and $z$ for $\sigma\tau$. Since $xy$ is a also a conjugation factor, we define the comparison coefficient to be $\comp^{\sigma, \tau}_{x,y,z}:=\sigma\left(\tau\left(\twist_{xy, z}\right)\right)$. We often omit superscript when the context is clear. Note that $\comp_{x,y,z}$ is a unit in $K$ with inverse $\sigma\left(\tau\left(\twist_{z, xy}\right)\right)$. By~\cref{lem:twist-spec1} and~\cref{lem:twist-spec2}, we have the following useful equalities
  \[
    \begin{aligned}
      xy &= \iota_{A}\left(\comp_{x,y,z}\right)z \\
      \iota_{A}\left(\comp_{x,y,z}^{-1}\right)xy &= z \\
      \iota_{A}\left(\comp_{x,y,z}\right) &= xyz^{-1}\\
      \iota_{A}\left(\comp_{x,y,z}^{-1}\right) &= zy^{-1}x^{-1}\\
      \dots &=\dots
    \end{aligned}.
  \]
  %If we have a conjugation sequence $x : \gal(K/F)\to A^{\star}$, instead of $\comp_{x_{\sigma},x_{\tau},x_{\sigma\tau}}^{\sigma,\tau}$, we simply write $\comp_{\sigma,\tau}^{x}$.
  \leanok
  \lean{GoodRep.conjFactorCompCoeff}
  % \uses{lem:twist-spec1, lem:twist-spec2}
\end{construction}

n25046.content:
\begin{lemma}\label{lem:compare-conj-factor-spec}
  Let $x : \gal(K/F) \to A^{\star}$ be a conjugation sequence. We have
  \[
    \comp_{x_{\rho}, x_{\sigma}, x_{\rho\sigma}}\,\comp_{x_{\rho\sigma},x_{\tau},x_{\rho\sigma\tau}} =
    \rho\left(\comp_{x_{\sigma},x_{\tau},x_{\sigma\tau}}\right)\,\comp_{x_{\rho}, x_{\sigma\tau}, x_{\rho\sigma\tau}}.
  \]
  \leanok
  \lean{GoodRep.conjFactorCompCoeff_comp_comp}
  % \uses{con:compare-conj-factors, def:conj-factor, con:br-base-change}
\end{lemma}

n25047.content:
\begin{proof}
  It is sufficient to make the following calculations:
  \begin{align}
   x_{\rho}\,x_{\sigma}x_{\tau} &= \iota_{A}\left(\comp_{x_{\rho},x_{\sigma},x_{\rho\sigma}}\right) \, \iota_{A}\left(\comp_{x_{\rho\sigma}, x_{\tau}, x_{\rho\sigma\tau}}\right)\, x_{\rho\sigma\tau}\label{eq:1}\\
   x_{\rho}\left(x_{\sigma}x_{\tau}\right) &= \iota_{A}\left(\rho\cdot\comp_{x_{\sigma},x_{\tau},x_{\sigma\tau}}\right)\,\iota_{A}\left(\comp_{x_{\rho},x_{\sigma\tau},x_{\rho\sigma\tau}}\right) x_{\rho\sigma\tau} \label{eq:2}
 \end{align}
 Then since $x_{\rho\sigma\tau}$ is invertible and $\iota_{A}$ is injective, we proved the desired result.

 \Cref{eq:1} is because: by the first equality in~\cref{con:compare-conj-factors} (twice)
 \[
   x_{\rho}x_{\sigma}x_{\tau}=\iota_{A}\left(\comp_{x_{\rho},x_{\sigma}, x_{\rho\sigma}}\right)x_{\rho\sigma}x_{\tau}=\iota_{A}\left(\comp_{x_{\rho},x_{\sigma},x_{\rho\sigma}}\right)\iota_{A}\left(\comp_{x_{\rho\sigma},x_{\tau},x_{\rho\sigma\tau}}\right)x_{\rho\sigma\tau}.
 \]
 \Cref{eq:2} is because: by~\cref{def:conj-factor}, we have
 \[\iota_{A}\left(\rho\cdot\comp_{x_{\sigma},x_{\tau},x_{\sigma\tau}}\right)x_{\rho}=x_{\rho}\iota_{A}\left(\comp_{x_{\sigma},x_{\tau},x_{\sigma\tau}}\right),\]
 therefore by~\cref{con:br-base-change}
 \[
   \begin{aligned}
     x_{\rho}\left(x_{\sigma}x_{\tau}\right) &= x_{\rho}\iota_{A}\left(\comp_{x_{\sigma},x_{\tau},x_{\sigma\tau}}\right)x_{\sigma\tau} \\
                                             &= \iota_{A}\left(\rho\cdot \comp_{x_{\sigma},x_{\tau},x_{\sigma\tau}}\right)x_{\rho}x_{\sigma\tau}\\
     &= \iota_{A}\left(\rho\cdot\comp_{x_{\sigma},x_{\tau},x_{\sigma\tau}}\right)\,\iota_{A}\left(\comp_{x_{\rho},x_{\sigma\tau},x_{\rho\sigma\tau}}\right)x_{\rho\sigma\tau}
   \end{aligned}.
 \]
\end{proof}

n25048.content:
\begin{construction}[from good representation to 2-cocycle]
  \label{con:good-rep-to-2-cocycles}
  Let $x$ be an $A$-conjugation sequence. We associate with $x$ a function $\mathcal{B}^{2}(x) : \gal(K/F)\times\gal(K/F)\to K^{\star}$ defined by
  \[
    (\sigma,\tau)\mapsto \comp_{x_{\sigma},x_{\tau},x_{\sigma\tau}}.
  \]
  We will write $\mathcal{B}^{2}(x)$ as $\mathcal{B}^{2}_{A, x}$, $\mathcal{B}^{2}_{A}(x)$ or $\mathcal{B}^{2}_{x}$ as well.
  \leanok
  \lean{GoodRep.toTwoCocycles}
\end{construction}

n25049.content:
\begin{lemma}
  For any $A$-conjugation sequence $x$, $\mathcal{B}^{2}_{x} \in \mathcal{B}^{2}\left(\gal(K/F), K^{\star}\right)$, that is $\mathcal{B}_{x}$ is indeed a 2-cocycle.
  \leanok
  \lean{GoodRep.isTwoCocyles}
  % \uses{lem:compare-conj-factor-spec}
\end{lemma}

n25051.content:
\begin{construction}\label{con:good-rep-iso-coeff}
  By~\cref{lem:good-rep-iso}, $A$ and $B$ are isomorphic as $F$-algebras, we use $e_{A,B}$ to denote an arbitrary $F$-algebra isomorphism between $A$ and $B$. When there is no confusion, we write $e$ instead of $e_{A, B}$ Since $e \circ \iota_{A}$ and $\iota_{B}$ are two $F$-algebra homomorphism from $K$ to $B$, by~\cref{thm:skolem-noether}, there exists some $u \in B^{\star}$ such that for all $r \in K$, we have $\iota_{B}(r) = ue\left(\iota_{A}(r)\right)u^{-1}$ (or equivalently, $u^{-1}\iota_{B}(r)u = e\left(\iota_{A}(r)\right)$). When there is confusion, we write $u_{A, B}$ instead of $u$.
  % \uses{lem:good-rep-iso}
\end{construction}

n25052.content:
\begin{lemma}\label{lem:iso-conj-coeff-spec2}
  For any $c \in K$, $\sigma\in\gal(K/F)$ and $A$-conjugation factor $x$ of $\sigma$, we have
  \[
    \iota_{B}\left(\sigma\cdot c\right) = ue(x)u^{-1}\,\iota_{B}(c)\,ue\left(x^{-1}\right)u^{-1}.
  \]
  \leanok
  \lean{GoodRep.isoConjCoeff_spec''}
  % \uses{def:conj-factor, con:good-rep-iso-coeff}
\end{lemma}

n25053.content:
\begin{proof}
  From~\cref{def:conj-factor}, we have $e\left(\iota_{A}(\sigma \cdot c)\right) = e\left(x\iota_{A}(c)x^{-1}\right)$. Substituting it in~\cref{con:good-rep-iso-coeff}, we get
  \[
    \begin{aligned}
      \iota_{B}(\sigma \cdot c) &= ue\left(x\iota_{A}(c)x^{-1}\right)u^{-1}\\
                                &= ue(x)e\left(\iota_{A}(c)\right)e\left(x^{-1}\right)u^{-1}\\
      &= ue(x)u^{-1}\iota_{B}(c)ue\left(x^{-1}\right)u^{-1}.
    \end{aligned}
  \]
\end{proof}

n25054.content:
\begin{construction}
  \label{con:push-forward-conj-factor}
  If $x$ is an $A$-conjugation factor for $\sigma$, we can obtain a $B$-conjugation factor for $\sigma$ by defining $B_{\star}x := ue(x)u^{-1}$ with inverse $ue\left(x^{-1}\right)u^{-1}$. We use~\cref{lem:iso-conj-coeff-spec2} to check that $B_{\star}x$ is indeed a conjugation factor for $\sigma$. If $y$ is a $B$-conjugation factor for $\sigma$, another useful constant is $v := \sigma\left(\twist_{y, B_{\star}x}\right)$. We have
  \[
    \begin{aligned}
    y &= \iota_{B}\left(v\right)\, B_{\star}x \\
      \iota_{B}\left(v\right) &= u e\left(\iota_{A}\left(v\right)\right)u^{-1}\\
      v^{-1} &= \sigma\left(\twist_{B_{\star}x, y}\right)
    \end{aligned}.
  \]
  We also write $v_{x,y}$ or even $v^{A,B}_{x, y}$ when we stress the importance of good representation $A$ and $B$ and their conjugation factor $x$ and $y$.
  % \uses{lem:iso-conj-coeff-spec2}
\end{construction}

n25055.content:
\begin{lemma}\label{lem:compare-to-2-cocycle-aux}
  Let $x$ be an $A$-conjugation sequence and $y$ a $B$-conjugation sequence.
  We have
  \[
    \comp_{y_{\sigma}, y_{\tau}, y_{\sigma\tau}} v_{x_{\sigma\tau},y_{\sigma\tau}} = v_{x_{\sigma},y_{\sigma}} \sigma\left(v_{x_{\tau},y_{\tau}}\right) \comp_{x_{\sigma},x_{\tau},x_{\sigma\tau}}.
  \]
  \leanok
  \lean{GoodRep.compare_conjFactorCompCoeff}
  % \uses{con:compare-conj-factors, con:push-forward-conj-factor, con:good-rep-iso-coeff, def:conj-factor}
\end{lemma}

n25057.content:
\begin{lemma}\label{lem:compare-to-2-cocycle}
  Let $x$ be an $A$-conjugation sequence and $y$ a $B$-conjugation sequence. We have
  \[
    \mathcal{B}^{2}_{B,y}(\sigma,\tau) v_{x_{\sigma\tau},y_{\sigma\tau}} =
    v_{x_{\sigma},y_{\sigma}} \sigma\left(v_{x_{\tau},y_{\tau}}\right) \mathcal{B}^{2}_{A,y}(\sigma,\tau).
  \]
  \leanok
  \lean{GoodRep.compare_toTwoCocycles}
  % \uses{con:good-rep-to-2-cocycles,lem:compare-to-2-cocycle-aux}
\end{lemma}

n25058.content:
\begin{proof}
  If we unfold~\cref{con:good-rep-to-2-cocycles}, we discover the lemma is saying exactly~\cref{lem:compare-to-2-cocycle-aux}.
\end{proof}

n25059.content:
\begin{corollary}\label{cor:to-2-cocycle-wd}
  Let $x$ be an $A$-conjugation sequence and $y$ a $B$-conjugation sequence. $\mathcal{B}^{2}_{A,x}$ and $\mathcal{B}^{2}_{B,y}$ are 2-cohomologous.
  \leanok
  \lean{GoodRep.compare_toTwoCocycles'}
  % \uses{def:second-group-coh, lem:compare-to-2-cocycle}
\end{corollary}

n25061.content:
\begin{construction}[from $\br(K/F)$ to $\HH^{2}\left(\gal(K/F), K^{\star}\right)$]\label{con:br-to-snd-coh}
  Let $X \in \br(K/F)$, by~\cref{cor:mem-relative-br-iff-good-rep}, $X$ admits a good representation $A$; by~\cref{con:exists-conj-seq}, $A$ admits a conjugation sequence $x$. We associate with $X$ an element $\HH^{2}(X) := \left[\mathcal{B}^{2}_{A,x}\right]$in $\HH^{2}\left(\gal(K/F),K^{\star}\right)$. By~\cref{cor:to-2-cocycle-wd}, for any other good representation $B$ and $B$-conjugation sequence $y$, we have $\left[\mathcal{B}^{2}_{A,x}\right]=\left[\mathcal{B}^{2}_{B,y}\right]$, hence we have a well-defined function $\HH^{2} : \br(K/F) \to \HH^{2}\left(\gal(K/F),K^{\star}\right)$.
  \leanok
  \lean{RelativeBrGroup.toSnd, RelativeBrGroup.toSnd_wd}
  % \uses{con:exists-conj-seq, cor:mem-relative-br-iff-good-rep,cor:to-2-cocycle-wd}
\end{construction}

n25062.content:
\begin{construction}[Cross product]\label{con:cross-product}
  Denote $\cross_{\mathfrak{a}}$ to be $\gal(K/F) \to K$, i.e. functions from $\gal(K/F)$ to $K$. Notationally, elements of $\cross_{\mathfrak{a}}$ are sequences in $K$ indexed by $\gal(K/F)$; we denote $\Delta^{\mfa}_{\sigma, c}$ to be the sequence with value $c$ at $\sigma$-th index and zero elsewhere. When $\mfa$ is clear from context, we will omit the superscript. We give $\cross_{\mathfrak{a}}$ the usual zero, addition, negation, that is, we give $\cross_{\mathfrak{a}}$ the normal additive abelian group structure. Since for each $c \in \cross_{\mathfrak{a}}$,
  \[
    c = \sum_{\sigma\in\gal(K/F)}\Delta_{\sigma, c(\sigma)},
    \]
    it is often, if not always, sufficient to consider the special cases of $\Delta_{\sigma, c}$ and extend the result linearly.
  For multiplications, we define the result of multiplying $\Delta_{\sigma, c},\Delta_{\tau, d} \cross_{\mathfrak{a}}$ to be $\Delta_{\sigma\tau, c\sigma(d)\, \mathfrak{a}(\sigma,\tau)}$. Immediately, if either $c$ or $d$ is $0$, the result of multiplication is also zero. That is, for all $c \in \cross_{\mfa}$, we have $c\cdot 0=0\cdot c =0$. For any $r \in F$ and $\Delta_{\sigma, c} \in \cross_{\mathfrak{a}}$, we define $r \cdot \Delta_{\sigma, c}$ to be $\Delta_{\sigma, r\cdot c}$.
  \leanok
  \lean{CrossProductAlgebraMul, CrossProductAlgebraSMul, CrossProductAlgebra.addCommGroup}
\end{construction}

n25063.content:
\begin{remark}
  When $K/F$ is infinite dimensional, the correct definition of $\cross_{\mathfrak{a}}$ is perhaps $\bigoplus_{\sigma\in\gal(K/F)}K$. But in Lean4, function type is easier to manipulate than direct sums. Since our scope is finite dimensional Galois extension, our definition is still accurate.
\end{remark}

n25064.content:
\begin{lemma}
  The cross product $\cross_{\mathfrak{a}}$ is a ring with the multiplicative unit $\Delta_{\mathsf{id}, \mathfrak{a}(\mathsf{id}, \mathsf{id})^{-1}}$. The $F$-action on $\cross_{\mathfrak{a}}$ defined by $r \cdot \Delta_{\sigma, c} := \Delta_{\sigma, r\cdot c}$ makes it an $F$-algebra.
  \leanok
  \lean{CrossProductAlgebra.algebra}
  % \uses{def:second-group-coh, lem:2-cocycle-one-one}
\end{lemma}

n25065.content:
\begin{proof}
  We verify the axioms of rings on elements of the form $\Delta_{\sigma, c}$. Let $\sigma,\tau,\rho\in\gal(K/F)$ and $a,b,c\in K$.
  \begin{itemize}
    \item associativity of multiplication. We need to check that $\Delta_{\sigma,a}\left(\Delta_{\tau,b}\Delta_{\rho,c}\right) = \left(\Delta_{\sigma,a}\Delta_{\tau,b}\right)\Delta_{\rho,c}$:
          \[
          \begin{aligned}
            \Delta_{\sigma, a}\left(\Delta_{\tau,b}\Delta_{\rho,c}\right)
            &= \Delta_{\sigma,a}\Delta_{\tau\rho,b\tau(c) \mathfrak{a}(\sigma,\tau)}\\
            &= \Delta_{\sigma\tau\rho,a\sigma(b)\sigma(\tau(c)) \sigma(\mathfrak{a}(\sigma, \tau))};\\
            %
            \left(\Delta_{\sigma,a}\Delta_{\tau,b}\right)\Delta_{\rho,c}
            &= \Delta_{\sigma\tau,a\sigma(b)\mathfrak{a}(\sigma,\tau)}\Delta_{\rho,c}\\
            &= \Delta_{\sigma\tau\rho,a\sigma(b)\mathfrak{a}(\sigma, \tau)\sigma(\tau(c))\mathfrak{a}(\sigma\tau, \rho)}.
          \end{aligned}
          \]
          Hence it is sufficient to check
          \[
          \sigma(\tau(c))\sigma(\mathfrak{a}(\sigma,\tau)) =
          \mathfrak{a}(\sigma,\tau)\sigma(\tau(c))\mathfrak{a}(\sigma\tau, \rho).
          \]
          This is the 2-cocycle condition in~\cref{def:second-group-coh} (modulo commutativity of $K$).
    \item multiplicative unit: we need to check $\Delta_{\sigma, a}\Delta_{\mathsf{id},\mathfrak{a}(\mathsf{id}, \mathsf{id})} = \Delta_{\mathsf{id},\mathfrak{a}(\mathsf{id},\mathsf{id})}\Delta_{\sigma, a} = \Delta_{\sigma, a}$. By multiple applications of~\cref{lem:2-cocycle-one-one}
          \[
          \begin{aligned}
            \Delta_{\mathsf{id},\mathfrak{a}(\mathsf{id}, \mathsf{id})^{-1}}\Delta_{\sigma, a}
            &= \Delta_{\sigma, \mathfrak{a}(\mathsf{id}, \mathsf{id})^{-1}a\mathfrak{a}(\mathsf{id},\sigma)}\\
            &= \Delta_{\sigma, \mathfrak{a}(\mathsf{id}, \mathsf{id}) a\mathfrak{a}(\mathsf{id},\mathsf{id})}\\
            &= \Delta_{\sigma, a} \\
            \Delta_{\sigma, a}\Delta_{\mathsf{id},\mathfrak{a}(\mathsf{id},\mathsf{id})^{-1}}
            &= \Delta_{\sigma, a\sigma(\mathfrak{a}(\id,\id))^{-1}\mathfrak{a}(\sigma,\id)}\\
            &=\Delta_{\sigma, a\sigma(\mfa(\id,\id))^{-1}\sigma(\mfa(\id, id))}\\
            &=\Delta_{\sigma, a}
          \end{aligned}
          \]
    \item distributivity: We need to check left-distributivity $\Delta_{\sigma, a}\left(\Delta_{\tau, b} + \Delta_{\rho, c}\right) = \Delta_{\sigma,a}\Delta_{\tau,b} + \Delta_{\sigma, a}\Delta_{\rho, c}$ and right distributivity $\left(\Delta_{\tau,b} + \Delta_{\rho,c}\right)\Delta_{\sigma,a} = \Delta_{\tau,b}\Delta_{\sigma,a} + \Delta_{\rho,c}\Delta_{\sigma,a}$. This is precisely what ``extend linearly'' means.
    \item $F$-algebra: We need to check for all $r \in F$, $\left(r\cdot \Delta_{\id,\mfa(\id,\id)^{-1}}\right)\Delta_{\sigma,c} = \Delta_{\sigma,c}\left(r\cdot\Delta_{\id,\mfa(\id,\id)^{-1}}\right)$. By~\cref{lem:2-cocycle-one-one}
          \[
          \begin{aligned}
            \left(r\cdot \Delta_{\id,\mfa(\id,\id)^{-1}}\right)\Delta_{\sigma,c}
            &= \Delta_{\id,r\cdot\mfa(\id,\id)^{-1}}\Delta_{\sigma,c}\\
            &= \Delta_{\sigma,\left(r\cdot\mfa(\id,\id)^{-1}\right)c\mfa(\id,\sigma)} \\
            &=\Delta_{\sigma,\left(r\cdot\mfa(\id,\id)^{-1}\right)c\mfa(\id,\id)} \\
            &= \Delta_{\sigma, r\cdot c}\\
            %
            \Delta_{\sigma,c}\left(r\cdot\Delta_{\id,\mfa(\id,\id)^{-1}}\right)
            &= \Delta_{\sigma,c}\Delta_{\id,r\cdot \mfa(\id,\id)^{-1}} \\
            &= \Delta_{\sigma,c\sigma\left(r\cdot\mfa(\id,\id)^{-1}\right)\mfa(\sigma,\id)}\\
            &=\Delta_{\sigma,c\left(r\cdot\sigma\left(\mfa(\id,\id)^{-1}\right)\right)\mfa(\id,\id)^{-1}}\\
            &= \Delta_{\sigma, c\left(r\cdot 1\right)}\\
            &=\Delta_{\sigma,r\cdot c}.
          \end{aligned}
          \]
  \end{itemize}
\end{proof}

